package net.civeira.phylax.features.access.userwebauthncredential.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AutenticatorVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property autenticator of user webauthn credential ")
  void test_autenticator_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> AutenticatorVO.tryFrom(null));
    Assertions.assertEquals("one", AutenticatorVO.from("one").getAutenticator());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AutenticatorVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AutenticatorVO.from("one").toString());
  }
}
